+function getFormattedDate() {
+    let date = new Date();
+    return date.getFullYear() + 
+        str_pad(date.getMonth() + 1, 2, '0', 'left') + 
+        str_pad(date.getDate(), 2, '0', 'left');
+}
+
+function str_pad(string, length, pad, direction) {
+    string = String(string);
+    while (string.length < length) {
+        if (direction === 'left') {
+            string = pad + string;
+        } else {
+            string = string + pad;
+        }
+    }
+    return string;
+}
