+    $condition_text = sanitize($_POST['condition']);
+    $fund_cluster = sanitize($_POST['fund_cluster']);
+    $remarks = sanitize($_POST['remarks']);
+    $barcode_data = !empty($_POST['barcode_data']) ? sanitize($_POST['barcode_data']) : null;
+    
+    $stmt = $conn->prepare("
+        UPDATE inventory SET 
+            article_name = ?, description = ?, uom = ?,
+            qty_physical_count = ?, unit_value = ?,
+            equipment_id = ?, section_id = ?, category = ?,
+            condition_text = ?, fund_cluster = ?, remarks = ?, 
+            barcode_data = ?, date_updated = NOW()
+        WHERE id = ?
+    ");
+    
+    $stmt->bind_param(
+        "sssddiisssssi",
+        $article_name, $description, $uom,
+        $quantity, $unit_value,
+        $equipment_id, $section_id, $category,
+        $condition_text, $fund_cluster, $remarks,
+        $barcode_data, $id
+    );
+    
+    if ($stmt->execute()) {
+        // AUDIT TRAIL LOGGING - Edit Inventory
+        if (function_exists('logDetailedActivity')) {
+            $changes = [];
+            $old_vals = [];
+            $new_vals = [];
+            
+            if ($old_data['article_name'] != $article_name) {
+                $changes[] = "article_name";
+                $old_vals['article_name'] = $old_data['article_name'];
+                $new_vals['article_name'] = $article_name;
+            }
+            if ($old_data['qty_physical_count'] != $quantity) {
+                $changes[] = "quantity";
+                $old_vals['quantity'] = $old_data['qty_physical_count'];
+                $new_vals['quantity'] = $quantity;
+            }
+            if ($old_data['unit_value'] != $unit_value) {
+                $changes[] = "unit_value";
+                $old_vals['unit_value'] = $old_data['unit_value'];
+                $new_vals['unit_value'] = $unit_value;
+            }
+            
+            logDetailedActivity(
+                'UPDATE',
+                $_SESSION['user_id'],
+                "Edited inventory item: {$article_name} - Changed: " . implode(', ', $changes),
+                'inventory',
+                $id,
+                !empty($old_vals) ? $old_vals : null,
+                !empty($new_vals) ? $new_vals : null,
+                ['property_no' => $old_data['property_no']]
+            );
+        }
+        
+        logActivity('Edit Inventory', $id, "Edited item: $article_name");
+        $_SESSION['success'] = "Inventory item updated successfully";
+    } else {
