+                                    <i class="fas fa-search"></i> View
+                                </button>
+                                <button class="btn btn-xs btn-primary" onclick="printBarcode('${item.barcode_data}', '${escapeHtml(item.article_name)} - ${escapeHtml(item.property_no)}')">
+                                    <i class="fas fa-print"></i> Print
+                                </button>
+                            </div>
+                        </div>
