+// Handle Add Multiple Barcodes to Existing Item
+elseif ($_SERVER['REQUEST_METHOD'] == 'POST' && isset($_POST['action']) && $_POST['action'] == 'add_multiple_barcodes' && isset($_POST['parent_id'])) {
+    $parent_id = (int)$_POST['parent_id'];
