+                    $original_item['category'], 
+                    $original_item['condition_text'],
+                    $original_item['fund_cluster'], 
+                    $original_item['remarks'], 
+                    $created_by, 
+                    $barcode_data
+                );
+                
+                if (!$stmt->execute()) {
+                    throw new Exception($conn->error);
+                }
+                $stmt->close();
+            }
+            
+            $conn->commit();
