+<script>
+// Calculate total value for add modal
+document.getElementById('add_quantity')?.addEventListener('input', calculateAddTotal);
+document.getElementById('add_unit_value')?.addEventListener('input', calculateAddTotal);
+document.getElementById('quantity')?.addEventListener('input', calculateTotal);
+document.getElementById('unit_value')?.addEventListener('input', calculateTotal);
+
+function calculateAddTotal() {
+    let quantity = parseFloat(document.getElementById('add_quantity').value) || 0;
+    let unitValue = parseFloat(document.getElementById('add_unit_value').value) || 0;
+    let total = quantity * unitValue;
+    document.getElementById('add_total_value').value = '₱' + total.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
+}
+
+function calculateTotal() {
+    let quantity = parseFloat(document.getElementById('quantity').value) || 0;
+    let unitValue = parseFloat(document.getElementById('unit_value').value) || 0;
+    let total = quantity * unitValue;
+    document.getElementById('total_value').value = '₱' + total.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
+}
+
+// Open Add Inventory Modal
+function openAddInventoryModal() {
+    document.getElementById('addInventoryForm').reset();
+    document.getElementById('add_quantity').value = '1';
+    document.getElementById('add_barcode_preview').innerHTML = '';
+    calculateAddTotal();
+    document.getElementById('addInventoryModal').style.display = 'block';
+}
+
+// Close Add Inventory Modal
+function closeAddInventoryModal() {
+    document.getElementById('addInventoryModal').style.display = 'none';
+}
+
