+function closeBarcodeModal() {
+    document.getElementById('barcodeModal').style.display = 'none';
+}
+
+function closeAddBarcodeModal() {
+    document.getElementById('addBarcodeModal').style.display = 'none';
+    document.getElementById('barcodePreviewGrid').innerHTML = '';
+}
+
+function closeAllBarcodesModal() {
+    document.getElementById('viewAllBarcodesModal').style.display = 'none';
+}
+
+// Generate barcode for add modal
+function generateAddBarcode() {
+    let prefix = 'INV';
+    let barcodeValue = prefix + getFormattedDate() + Math.floor(1000 + Math.random() * 9000);
+    document.getElementById('add_barcode_data').value = barcodeValue;
+    document.getElementById('add_barcode_preview').innerHTML = '<i class="fas fa-check-circle"></i> Barcode generated: ' + barcodeValue;
+}
+
+// Generate barcode for edit modal
+function generateBarcodeForEdit() {
+    let prefix = 'INV';
+    let barcodeValue = prefix + getFormattedDate() + Math.floor(1000 + Math.random() * 9000);
+    document.getElementById('barcode_data').value = barcodeValue;
+    document.getElementById('barcodePreview').innerHTML = '<i class="fas fa-check-circle"></i> Barcode generated: ' + barcodeValue;
+}
+
+// Submit Add Inventory via AJAX
+function submitAddInventory() {
+    let formData = {
+        action: 'add_inventory_ajax',
+        article_name: document.getElementById('add_article_name').value,
+        description: document.getElementById('add_description').value,
+        category: document.getElementById('add_category').value,
+        uom: document.getElementById('add_uom').value,
+        quantity: document.getElementById('add_quantity').value,
+        unit_value: document.getElementById('add_unit_value').value,
+        equipment_id: document.getElementById('add_equipment_id').value,
+        section_id: document.getElementById('add_section_id').value,
+        condition: document.getElementById('add_condition').value,
+        fund_cluster: document.getElementById('add_fund_cluster').value,
+        remarks: document.getElementById('add_remarks').value,
+        barcode_data: document.getElementById('add_barcode_data').value
+    };
+    
+    // Validation
+    if (!formData.article_name) {
+        alert('Please enter article name');
+        return;
+    }
+    if (!formData.uom) {
+        alert('Please select unit of measurement');
+        return;
+    }
+    if (parseFloat(formData.quantity) <= 0) {
+        alert('Please enter valid quantity');
+        return;
+    }
+    if (parseFloat(formData.unit_value) <= 0) {
+        alert('Please enter valid unit value');
+        return;
+    }
+    
+    let submitBtn = event.target;
+    let originalText = submitBtn.innerHTML;
+    submitBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Saving...';
+    submitBtn.disabled = true;
+    
+    fetch(window.location.href, {
+        method: 'POST',
+        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
+        body: new URLSearchParams(formData)
+    })
+    .then(response => response.json())
+    .then(data => {
+        if (data.success) {
+            alert('Success: ' + data.message);
+            closeAddInventoryModal();
+            location.reload();
+        } else {
+            alert('Error: ' + data.message);
+        }
+    })
+    .catch(error => {
+        alert('Error: ' + error);
+    })
+    .finally(() => {
+        submitBtn.innerHTML = originalText;
+        submitBtn.disabled = false;
+    });
+}
+
+// Open Add Barcode Modal
+function openAddBarcodeModal(itemId, itemName) {
+    document.getElementById('parent_id').value = itemId;
+    document.getElementById('addBarcodeModalTitle').textContent = 'Add Barcodes to ' + itemName;
+    document.getElementById('addBarcodeModal').style.display = 'block';
+}
+
+// Preview barcodes
+function previewBarcodes() {
+    let prefix = document.getElementById('barcode_prefix').value;
+    let quantity = parseInt(document.getElementById('barcode_quantity').value) || 5;
+    let preview = document.getElementById('barcodePreviewGrid');
+    preview.innerHTML = '<div class="loading"><i class="fas fa-spinner fa-spin"></i><br>Generating barcodes...</div>';
+    
+    fetch('?generate_multiple_preview=1&prefix=' + encodeURIComponent(prefix) + '&quantity=' + quantity)
+        .then(response => response.json())
+        .then(data => {
+            if (data.success) {
+                let html = '';
+                data.barcodes.forEach(barcode => {
+                    html += `<div class="barcode-preview-card"><div class="item-number">Item ${barcode.index}</div><div class="barcode-value">${barcode.value}</div></div>`;
+                });
+                preview.innerHTML = html;
+            } else {
+                preview.innerHTML = '<div class="alert alert-danger">Error: ' + data.error + '</div>';
+            }
+        })
+        .catch(error => {
+            preview.innerHTML = '<div class="alert alert-danger">Error generating barcodes</div>';
+        });
+}
+
+// Barcode Functions
+function showBarcodeModal(barcodeData, itemName) {
+    document.getElementById('barcodeModalTitle').textContent = 'Barcode - ' + itemName;
+    document.getElementById('barcodeModalImage').innerHTML = '<img src="generate_barcode.php?code=' + encodeURIComponent(barcodeData) + '&width=300&height=80" alt="Barcode" style="max-width: 100%;">';
+    document.getElementById('barcodeModalNumber').textContent = barcodeData;
+    document.getElementById('barcodeModal').style.display = 'block';
