-LIMIT 1
-) THEN 1 ELSE 0 END as is_issued,
-CASE WHEN i.property_no LIKE '%-%' THEN 1 ELSE 0 END as is_multiple
-FROM inventory i
-LEFT JOIN equipment e ON i.equipment_id = e.id
-LEFT JOIN sections s ON i.section_id = s.id
-WHERE 1=1
