+if (!$stmt->execute()) {
+throw new Exception($conn->error);
+}
+$stmt->close();
+}
+
+$conn->commit();
+logActivity('Add Multiple Barcodes', $parent_id, "Added $barcode_quantity barcode(s) to item: " . $original_item['article_name']);
