+<script>
+// Calculate total value for edit modal
+document.getElementById('quantity')?.addEventListener('input', calculateTotal);
+document.getElementById('unit_value')?.addEventListener('input', calculateTotal);
+
+function calculateTotal() {
+    let quantity = parseFloat(document.getElementById('quantity').value) || 0;
+    let unitValue = parseFloat(document.getElementById('unit_value').value) || 0;
+    let total = quantity * unitValue;
+    document.getElementById('total_value').value = '₱' + total.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
+}
+
+// Open Add Inventory Modal (iframe)
+function openAddInventoryModal() {
+    document.getElementById('addInventoryModal').style.display = 'block';
+}
+
+// Close Add Inventory Modal
+function closeAddInventoryModal() {
+    document.getElementById('addInventoryModal').style.display = 'none';
+}
+
+// Refresh iframe and close
+function refreshIframeAndClose() {
+    let iframe = document.querySelector('#addInventoryModal iframe');
+    if (iframe) {
+        iframe.contentWindow.location.reload();
+    }
+    setTimeout(() => {
+        location.reload();
+    }, 500);
+}
+
+// Close Modal
+function closeModal() {
+    document.getElementById('inventoryModal').style.display = 'none';
+    window.location.href = '<?php echo SITE_URL; ?>/admin/all_inventory.php';
+}
+
+function closeViewModal() {
+    document.getElementById('viewModal').style.display = 'none';
+}
+
+function closeBarcodeModal() {
+    document.getElementById('barcodeModal').style.display = 'none';
+}
+
+function closeAddBarcodeModal() {
+    document.getElementById('addBarcodeModal').style.display = 'none';
+    document.getElementById('barcodePreviewGrid').innerHTML = '';
+}
+
+function closeAllBarcodesModal() {
+    document.getElementById('viewAllBarcodesModal').style.display = 'none';
+}
+
+// Generate barcode for edit modal
+function generateBarcodeForEdit() {
+    let prefix = 'INV';
+    let barcodeValue = prefix + getFormattedDate() + Math.floor(1000 + Math.random() * 9000);
+    document.getElementById('barcode_data').value = barcodeValue;
+    document.getElementById('barcodePreview').innerHTML = '<i class="fas fa-check-circle"></i> Barcode generated: ' + barcodeValue;
+}
+
+// Open Add Barcode Modal
+function openAddBarcodeModal(itemId, itemName) {
+    document.getElementById('parent_id').value = itemId;
+    document.getElementById('addBarcodeModalTitle').textContent = 'Add Barcodes to ' + itemName;
+    document.getElementById('addBarcodeModal').style.display = 'block';
+}
+
+// Preview barcodes
+function previewBarcodes() {
+    let prefix = document.getElementById('barcode_prefix').value;
+    let quantity = parseInt(document.getElementById('barcode_quantity').value) || 5;
+    let preview = document.getElementById('barcodePreviewGrid');
+    preview.innerHTML = '<div class="loading"><i class="fas fa-spinner fa-spin"></i><br>Generating barcodes...</div>';
+    
+    fetch('?generate_multiple_preview=1&prefix=' + encodeURIComponent(prefix) + '&quantity=' + quantity)
+        .then(response => response.json())
+        .then(data => {
+            if (data.success) {
+                let html = '';
+                data.barcodes.forEach(barcode => {
+                    html += `<div class="barcode-preview-card"><div class="item-number">Item ${barcode.index}</div><div class="barcode-value">${barcode.value}</div></div>`;
+                });
+                preview.innerHTML = html;
+            } else {
+                preview.innerHTML = '<div class="alert alert-danger">Error: ' + data.error + '</div>';
+            }
+        })
+        .catch(error => {
+            preview.innerHTML = '<div class="alert alert-danger">Error generating barcodes</div>';
+        });
+}
+
+// Barcode Functions
+function showBarcodeModal(barcodeData, itemName) {
+    document.getElementById('barcodeModalTitle').textContent = 'Barcode - ' + itemName;
+    document.getElementById('barcodeModalImage').innerHTML = '<img src="generate_barcode.php?code=' + encodeURIComponent(barcodeData) + '&width=300&height=80" alt="Barcode" style="max-width: 100%;">';
+    document.getElementById('barcodeModalNumber').textContent = barcodeData;
+    document.getElementById('barcodeModal').style.display = 'block';
+}
+
+function printCurrentBarcode() {
+    let barcodeData = document.getElementById('barcodeModalNumber').textContent;
+    let itemName = document.getElementById('barcodeModalTitle').textContent.replace('Barcode - ', '');
+    printBarcode(barcodeData, itemName);
+}
+
+function printBarcode(barcodeData, itemName) {
+    let printWindow = window.open('', '_blank');
+    printWindow.document.write(`
+        <html><head><title>Print Barcode</title>
+        <style>body{text-align:center;font-family:Arial,sans-serif;margin:20px;padding:20px;}
+        .barcode-container{border:2px solid #6B8CFF;border-radius:10px;padding:20px;max-width:400px;margin:0 auto;}
+        .barcode-img{max-width:100%;height:auto;}.item-name{font-size:14px;font-weight:bold;color:#6B8CFF;margin-top:10px;}
+        .barcode-number{font-family:monospace;font-size:12px;margin-top:5px;}</style>
+        </head><body>
+        <div class="barcode-container">
+        <img src="generate_barcode.php?code=${encodeURIComponent(barcodeData)}&width=400&height=100" class="barcode-img">
+        <div class="item-name">${itemName}</div>
+        <div class="barcode-number">${barcodeData}</div>
+        </div>
+        <script>window.onload=function(){window.print();window.close();}<\/script>
+        </body></html>
+    `);
+    printWindow.document.close();
+}
+
+// View all barcodes for a multiple set
+function viewAllBarcodes(propertyNo, itemName) {
+    document.getElementById('allBarcodesModalTitle').textContent = 'All Barcodes - ' + itemName;
+    document.getElementById('allBarcodesContent').innerHTML = '<div class="loading"><i class="fas fa-spinner fa-spin"></i> Loading...</div>';
+    document.getElementById('viewAllBarcodesModal').style.display = 'block';
+    
+    fetch('?get_multiple_items=1&property_no=' + encodeURIComponent(propertyNo))
+        .then(response => response.json())
+        .then(data => {
+            if (data.success && data.items.length > 0) {
+                let html = `<div class="all-barcodes-grid">`;
+                data.items.forEach((item, index) => {
+                    html += `
+                        <div class="barcode-item-card">
+                            <div class="item-property">Item ${index + 1}: ${item.property_no}</div>
+                            <div><img src="generate_barcode.php?code=${item.barcode_data}&width=250&height=60" style="max-width:100%;"></div>
+                            <div class="barcode-value">${item.barcode_data}</div>
+                            <div class="item-actions">
+                                <button class="btn btn-xs btn-secondary" onclick="showBarcodeModal('${item.barcode_data}', '${item.article_name} - ${item.property_no}')">View</button>
+                                <button class="btn btn-xs btn-primary" onclick="printBarcode('${item.barcode_data}', '${item.article_name} - ${item.property_no}')">Print</button>
+                            </div>
+                        </div>
+                    `;
+                });
+                html += '</div>';
+                document.getElementById('allBarcodesContent').innerHTML = html;
+            } else {
+                document.getElementById('allBarcodesContent').innerHTML = '<div class="alert alert-warning">No related items found.</div>';
+            }
+        })
+        .catch(error => {
+            document.getElementById('allBarcodesContent').innerHTML = '<div class="alert alert-danger">Error loading barcodes</div>';
+        });
+}
+
+function printAllBarcodes() {
+    let content = document.getElementById('allBarcodesContent').innerHTML;
+    let title = document.getElementById('allBarcodesModalTitle').textContent;
+    let printWindow = window.open('', '_blank');
+    printWindow.document.write(`
+        <html><head><title>${title}</title>
+        <style>.barcodes-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:20px;}
+        .barcode-item-card{border:2px solid #6B8CFF;padding:15px;text-align:center;border-radius:8px;page-break-inside:avoid;}
+        .item-actions{display:none;}@media print{.item-actions{display:none;}}</style>
+        </head><body><h2>${title}</h2><div class="barcodes-grid">
+        ${content.replace(/<button.*?<\/button>/g, '').replace(/<div class="item-actions">[\s\S]*?<\/div>/g, '')}
+        </div><script>window.onload=function(){window.print();window.close();}<\/script></body></html>
+    `);
+    printWindow.document.close();
+}
+
+// View Item Details
+function viewItem(itemId) {
+    fetch('?ajax=get_item&id=' + itemId)
+        .then(response => response.json())
+        .then(data => {
+            if (data.success) {
+                let item = data.data;
+                let isMultipleSet = item.property_no && item.property_no.includes('-');
+                let content = `
+                    <div>
+                        <h3 style="color: var(--primary);">${escapeHtml(item.article_name)}</h3>
+                        ${item.barcode_data ? `<div style="text-align:center;margin:20px 0;padding:20px;background:var(--light);border-radius:8px;">
+                            <img src="generate_barcode.php?code=${item.barcode_data}&width=300&height=80" style="max-width:100%;">
+                            <br><span style="font-family:monospace;">${item.barcode_data}</span>
+                            <br><button class="btn btn-primary" onclick="printBarcode('${item.barcode_data}', '${item.article_name}')">Print Barcode</button>
+                        </div>` : '<p>No barcode assigned.</p>'}
+                        ${isMultipleSet ? `<div style="margin:15px 0;padding:10px;background:var(--accent-light);border-radius:5px;">
+                            <small>This item is part of a multiple set. <button class="btn btn-xs btn-primary" onclick="viewAllBarcodes('${item.property_no}', '${item.article_name}')">View All Barcodes</button></small>
+                        </div>` : ''}
+                        <table style="width:100%">
